from pathlib import Path
import base64

root = Path(__file__).parent
options = [
    ('A', 'Docked inspector', 'Recommended', 'One continuous reading area, separated from the terminal by a theme-derived background and a fine edge.', 'Smallest change. Keeps the full reading width and feels like part of the window.'),
    ('B', 'Inset reading sheet', '', 'A narrow gutter frames an opaque sheet. The brief and history share one clearly bounded document.', 'Strongest outline. Costs 24 points of reading width and adds another frame inside the window.'),
    ('C', 'Two-tone split', '', 'A brighter summary area above a quieter timeline. Background levels reinforce the existing resizable split.', 'Clearest summary/history distinction. The additional background break gives the panel more visual structure.')
]

def image(theme, option, alt):
    data = base64.b64encode((root / f'{theme}-{option}.png').read_bytes()).decode()
    width, height = (360, 820) if theme == "warm" else (450, 480 if theme == "light" else 690)
    return f'<img src="data:image/png;base64,{data}" alt="{alt}" width="{width}" height="{height}">'

parts = ['<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Graftty Context design options</title><style>\n*{box-sizing:border-box}body{margin:0;background:#f1f0ec;color:#25282d;font:14px/1.5 -apple-system,BlinkMacSystemFont,"Helvetica Neue",sans-serif;-webkit-font-smoothing:antialiased}main{max-width:1500px;margin:auto;padding:36px 28px 44px}h1,h2,h3,p{margin:0}h1{font-size:29px;line-height:1.2;letter-spacing:-.8px;font-weight:650}h2{font-size:20px;line-height:1.3;letter-spacing:-.35px}h3{font-size:16px;font-weight:600}.eyebrow{font-size:12px;color:#62686c;margin-bottom:10px}.intro{max-width:830px;margin:12px 0 22px;color:#51585c;font-size:15px}.ground{display:flex;gap:10px 28px;flex-wrap:wrap;border-top:1px solid #d3d4d0;border-bottom:1px solid #d3d4d0;padding:13px 0;margin-bottom:26px;color:#555d61;font-size:12px}.options{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:24px}.label{display:flex;align-items:baseline;gap:9px;margin-bottom:9px}.letter{color:#71787d;font-size:13px}.recommend{color:#39694f;font-size:11px;font-weight:500;margin-left:auto}.pitch{color:#596166;min-height:68px;font-size:13px}.image{border-radius:10px;overflow:hidden;border:1px solid #b9bebf;background:#25292f;box-shadow:0 2px 5px #25282d0b;margin-top:15px}img{display:block;width:100%;height:auto}.tradeoff{font-size:12px;color:#51595e;margin-top:13px;min-height:53px}.section{margin-top:34px;padding-top:24px;border-top:1px solid #d3d4d0}.section>p{margin:8px 0 19px;color:#596166;max-width:930px}.compact .pitch{min-height:0}.compact .image{margin-top:10px}.compact .image img{aspect-ratio:450/480}.mobile{max-width:330px;margin:0 auto}.mobile .image img{aspect-ratio:360/820}.mobile .image{border-radius:15px}.sub{font-size:12px;color:#62686c;margin-top:8px}.recommendation{margin-top:34px;border-top:1px solid #d3d4d0;padding-top:24px;display:grid;grid-template-columns:1.2fr 1fr;gap:40px}.recommendation p{margin-top:8px;color:#51595e}.foot{margin-top:28px;font-size:11px;color:#677075}a{color:#315f85}a:focus-visible{outline:2px solid #315f85;outline-offset:4px}code{font-size:12px} @media(max-width:1000px){.options{gap:16px}.pitch{min-height:100px}.label{flex-wrap:wrap}.recommend{margin-left:0}.recommendation{gap:24px}}@media(max-width:760px){main{padding:24px 18px}.options,.recommendation{grid-template-columns:1fr}.options{gap:30px}.options>article{max-width:480px;width:100%;margin:auto}.pitch,.tradeoff{min-height:0}.ground{gap:9px 20px}h1{font-size:26px}.mobile{max-width:360px}}\n</style></head><body><main><div class="eyebrow">Graftty / Context sidebar / Native design studies</div><h1>Give Context its own place.</h1><p class="intro">Three treatments for the same brief and timeline. Each keeps the brief at the top and uses the terminal theme as its color source. These are native SwiftUI mockups, not changes to the running app.</p><div class="ground"><span>Top-aligned brief, including empty states</span><span>Opaque reading area</span><span>Resizable summary/history split</span><span>360-point inspector width</span></div><section class="options" aria-label="Dark palette design options">']
for n, (letter, title, tag, pitch, tradeoff) in enumerate(options, 1):
    parts.append(f'<article><div class="label"><span class="letter">{letter}</span><h3>{title}</h3><span class="recommend">{tag}</span></div><p class="pitch">{pitch}</p><div class="image">{image("dark", n, f"Option {letter}: {title}, dark palette, beside the terminal")}</div><p class="tradeoff">{tradeoff}</p></article>')
parts.append('</section><section class="section"><h2>Light palette, before the first report</h2><p>The identity and empty message start under the toolbar. A and B let a short brief use its natural height. C deliberately reserves a little more space for the summary. All leave the history available below.</p><div class="options compact">')
for n, (letter, title, *_rest) in enumerate(options, 1):
    parts.append(f'<article><h3>{letter} / {title}</h3><div class="image">{image("light", n, f"Option {letter}, light palette with top-aligned empty state")}</div></article>')
parts.append('</div></section><section class="section"><h2>Warm palette, mobile drawer study</h2><p>The same hierarchy at 360 points with larger body text. The gutter in B is more noticeable at this width. These are native view renders, not iOS Simulator captures; gesture and accessibility behavior are outside this study.</p><div class="options">')
for n, (letter, title, *_rest) in enumerate(options, 1):
    parts.append(f'<article><div class="mobile"><h3>{letter} / {title}</h3><div class="image">{image("warm", n, f"Option {letter}, warm mobile-width drawer")}</div></div></article>')
parts.append('</div></section><section class="recommendation"><div><h2>I’d start with A.</h2><p>It makes Context distinct without adding a second container or narrowing the text. If the brief and history still feel too similar, C makes their roles more explicit.</p></div><div><h3>Theme behavior</h3><p>These studies blend the Ghostty background toward its foreground. Dark palettes use more separation than light ones. No fixed gray, blue panel fill, or reliance on blur. A production implementation would also check low-contrast and unusual custom themes.</p><p class="sub">The layout remains distinct through the edge, inset, or section break even when a palette offers limited color separation.</p></div></section><p class="foot">Sample content and palettes. References: <a href="https://github.com/ceorkm/macos-design-skill">macOS design skill</a> for native hierarchy, type and restrained chrome; design-taste-frontend for audit-first exploration and explicit tradeoffs. Theme requirements and top alignment take precedence over generic styling defaults.</p></main></body></html>')
root.joinpath('index.html').write_text(''.join(parts))
print('Wrote self-contained design board')
